"""Tiny word-count tool: prints lines, words and chars of a file."""

import sys


def count(text):
    """Return a (lines, words, chars) tuple for text."""
    return len(text.splitlines()), len(text.split()), len(text)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 1:
        print("usage: python3 wordcount.py FILE", file=sys.stderr)
        return 2
    with open(argv[0], encoding="utf-8") as f:
        lines, words, chars = count(f.read())
    print(lines, words, chars)
    return 0


if __name__ == "__main__":
    sys.exit(main())

from wordcount import count, main


def test_simple_text():
    assert count("hello world\nfoo bar baz\n") == (2, 5, 24)


def test_single_line_no_newline():
    assert count("one two three") == (1, 3, 13)


def test_main_prints_counts(tmp_path, capsys):
    path = tmp_path / "sample.txt"
    path.write_text("a b\nc\n", encoding="utf-8")
    assert main([str(path)]) == 0
    assert capsys.readouterr().out == "2 3 6\n"


def test_main_usage_error(capsys):
    assert main([]) == 2
    assert "usage" in capsys.readouterr().err

"""Tiny word-count tool: prints lines, words and chars of a file."""

import json
import sys


def count(text):
    """Return a (lines, words, chars) tuple for text."""
    return len(text.splitlines()), len(text.split()), len(text)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    as_json = "--json" in argv
    paths = [arg for arg in argv if arg != "--json"]
    if len(paths) != 1:
        print("usage: python3 wordcount.py [--json] FILE", file=sys.stderr)
        return 2
    with open(paths[0], encoding="utf-8") as f:
        lines, words, chars = count(f.read())
    if as_json:
        counts = {"lines": lines, "words": words, "chars": chars}
        print(json.dumps(counts, separators=(",", ":")))
    else:
        print(lines, words, chars)
    return 0


if __name__ == "__main__":
    sys.exit(main())
